  ChatBskyGroupCreateGroup: {
    lexicon: 1,
    id: "chat.bsky.group.createGroup",
    defs: {
      main: {
        type: "procedure",
        description: "Creates a group convo, specifying the members to be added to it. Unlike getConvoForMembers, this isn't idempotent. It will create new groups even if the membership is identical to pre-existing groups. Will create 'request' membership for all members, except the owner who is 'accepted'.",
        errors: [
          {
            name: "AccountSuspended"
          },
          {
            name: "BlockedActor"
          },
          {
            name: "BlockedSubject"
          },
          {
            name: "NewAccountCannotCreateGroup"
          },
          {
            name: "NotFollowedBySender"
          },
          {
            name: "RecipientNotFound"
          },
          {
            name: "UserForbidsGroups"
          }
        ],
        input: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["members", "name"],
            properties: {
              members: {
                type: "array",
                maxLength: 49,
                items: {
                  type: "string",
                  format: "did"
                }
              },
              name: {
                type: "string",
                minLength: 1,
                maxGraphemes: 50,
                maxLength: 500
              }
            }
          }
        },
        output: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["convo"],
            properties: {
              convo: {
                type: "ref",
                ref: "lex:chat.bsky.convo.defs#convoView"
              }
            }
          }
        }
      }
    }
  },
  ChatBskyGroupCreateJoinLink: {
    lexicon: 1,
    id: "chat.bsky.group.createJoinLink",
    defs: {
      main: {
        type: "procedure",
        description: "Creates a join link for the group convo.",
        errors: [
          {
            name: "EnabledJoinLinkAlreadyExists"
          },
          {
            name: "InvalidConvo"
          },
          {
            name: "InsufficientRole"
          }
        ],
        input: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["convoId", "joinRule"],
            properties: {
              convoId: {
                type: "string"
              },
              requireApproval: {
                type: "boolean",
                default: false
              },
              joinRule: {
                type: "ref",
                ref: "lex:chat.bsky.group.defs#joinRule"
              }
            }
          }
        },
        output: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["joinLink"],
            properties: {
              joinLink: {
                type: "ref",
                ref: "lex:chat.bsky.group.defs#joinLinkView"
              }
            }
          }
        }
      }
    }
  },
  ChatBskyGroupDefs: {
    lexicon: 1,
    id: "chat.bsky.group.defs",
    defs: {
      linkEnabledStatus: {
        type: "string",
        knownValues: ["enabled", "disabled"]
      },
      joinRule: {
        type: "string",
        knownValues: ["anyone", "followedByOwner"]
      },
      joinLinkView: {
        description: "Join link view to be used within a group view, so the convo is surrounding, not specified inside this view.",
        type: "object",
        required: [
          "code",
          "enabledStatus",
          "requireApproval",
          "joinRule",
          "createdAt"
        ],
        properties: {
          code: {
            type: "string"
          },
          enabledStatus: {
            type: "ref",
            ref: "lex:chat.bsky.group.defs#linkEnabledStatus"
          },
          requireApproval: {
            type: "boolean"
          },
          joinRule: {
            type: "ref",
            ref: "lex:chat.bsky.group.defs#joinRule"
          },
          createdAt: {
            type: "string",
            format: "datetime"
          }
        }
      },
      joinLinkPreviewView: {
        description: "Preview that can be shown in feeds, including to unauthenticated viewers.",
        type: "object",
        required: [
          "convoId",
          "code",
          "name",
          "owner",
          "memberCount",
          "memberLimit",
          "requireApproval",
          "joinRule"
        ],
        properties: {
          convoId: {
            type: "string"
          },
          code: {
            type: "string"
          },
          name: {
            type: "string"
          },
          owner: {
            type: "ref",
            ref: "lex:chat.bsky.actor.defs#profileViewBasic"
          },
          memberCount: {
            type: "integer"
          },
          memberLimit: {
            type: "integer"
          },
          requireApproval: {
            type: "boolean"
          },
          joinRule: {
            type: "ref",
            ref: "lex:chat.bsky.group.defs#joinRule"
          },
          convo: {
            type: "ref",
            ref: "lex:chat.bsky.convo.defs#convoView",
            description: "Present only if the request is authenticated and the user is a member of the group."
          },
          viewer: {
            type: "ref",
            ref: "lex:chat.bsky.group.defs#joinLinkViewerState"
          }
        }
      },
      disabledJoinLinkPreviewView: {
        description: "Preview for a disabled join link. Carries only the code so clients can correlate with the input and render a disabled state.",
        type: "object",
        required: ["code"],
        properties: {
          code: {
            type: "string"
          }
        }
      },
      invalidJoinLinkPreviewView: {
        description: "Preview for a join link code that does not map to an existing link. Carries only the code so clients can correlate with the input and render an invalid state.",
        type: "object",
        required: ["code"],
        properties: {
          code: {
            type: "string"
          }
        }
      },
      joinLinkViewerState: {
        type: "object",
        properties: {
          requestedAt: {
            type: "string",
            format: "datetime"
          }
        }
      },
      joinRequestView: {
        description: "A join request from the perspective of the group owner.",
        type: "object",
        required: ["convoId", "requestedBy", "requestedAt"],
        properties: {
          convoId: {
            type: "string"
          },
          requestedBy: {
            type: "ref",
            ref: "lex:chat.bsky.actor.defs#profileViewBasic"
          },
          requestedAt: {
            type: "string",
            format: "datetime"
          }
        }
      },
      joinRequestConvoView: {
        description: "A join request from the perspective of the requester, including enough group context to render the request in a list (e.g. group name, owner, member count).",
        type: "object",
        required: [
          "convoId",
          "name",
          "owner",
          "memberCount",
          "memberLimit",
          "viewer"
        ],
        properties: {
          convoId: {
            type: "string"
          },
          name: {
            type: "string"
          },
          owner: {
            type: "ref",
            ref: "lex:chat.bsky.actor.defs#profileViewBasic"
          },
          memberCount: {
            type: "integer"
          },
          memberLimit: {
            type: "integer"
          },
          viewer: {
            type: "ref",
            ref: "lex:chat.bsky.group.defs#joinLinkViewerState"
          }
        }
      }
    }
  },
