  ToolsOzoneHostingGetAccountHistory: {
    lexicon: 1,
    id: "tools.ozone.hosting.getAccountHistory",
    defs: {
      main: {
        type: "query",
        description: "Get account history, e.g. log of updated email addresses or other identity information.",
        parameters: {
          type: "params",
          required: ["did"],
          properties: {
            did: {
              type: "string",
              format: "did"
            },
            events: {
              type: "array",
              items: {
                type: "string",
                knownValues: [
                  "accountCreated",
                  "emailUpdated",
                  "emailConfirmed",
                  "passwordUpdated",
                  "handleUpdated"
                ]
              }
            },
            cursor: {
              type: "string"
            },
            limit: {
              type: "integer",
              minimum: 1,
              maximum: 100,
              default: 50
            }
          }
        },
        output: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["events"],
            properties: {
              cursor: {
                type: "string"
              },
              events: {
                type: "array",
                items: {
                  type: "ref",
                  ref: "lex:tools.ozone.hosting.getAccountHistory#event"
                }
              }
            }
          }
        }
      },
      event: {
        type: "object",
        required: ["details", "createdBy", "createdAt"],
        properties: {
          details: {
            type: "union",
            refs: [
              "lex:tools.ozone.hosting.getAccountHistory#accountCreated",
              "lex:tools.ozone.hosting.getAccountHistory#emailUpdated",
              "lex:tools.ozone.hosting.getAccountHistory#emailConfirmed",
              "lex:tools.ozone.hosting.getAccountHistory#passwordUpdated",
              "lex:tools.ozone.hosting.getAccountHistory#handleUpdated"
            ]
          },
          createdBy: {
            type: "string"
          },
          createdAt: {
            type: "string",
            format: "datetime"
          }
        }
      },
      accountCreated: {
        type: "object",
        required: [],
        properties: {
          email: {
            type: "string"
          },
          handle: {
            type: "string",
            format: "handle"
          }
        }
      },
      emailUpdated: {
        type: "object",
        required: ["email"],
        properties: {
          email: {
            type: "string"
          }
        }
      },
      emailConfirmed: {
        type: "object",
        required: ["email"],
        properties: {
          email: {
            type: "string"
          }
        }
      },
      passwordUpdated: {
        type: "object",
        required: [],
        properties: {}
      },
      handleUpdated: {
        type: "object",
        required: ["handle"],
        properties: {
          handle: {
            type: "string",
            format: "handle"
          }
        }
      }
    }
  },
  ToolsOzoneModerationCancelScheduledActions: {
    lexicon: 1,
    id: "tools.ozone.moderation.cancelScheduledActions",
    defs: {
      main: {
        type: "procedure",
        description: "Cancel all pending scheduled moderation actions for specified subjects",
        input: {
          encoding: "application/json",
          schema: {
            type: "object",
            required: ["subjects"],
            properties: {
              subjects: {
                type: "array",
                maxLength: 100,
                items: {
                  type: "string",
                  format: "did"
                },
                description: "Array of DID subjects to cancel scheduled actions for"
              },
              comment: {
                type: "string",
                description: "Optional comment describing the reason for cancellation"
              }
            }
          }
        },
        output: {
          encoding: "application/json",
          schema: {
            type: "ref",
            ref: "lex:tools.ozone.moderation.cancelScheduledActions#cancellationResults"
          }
        }
      },
      cancellationResults: {
        type: "object",
        required: ["succeeded", "failed"],
        properties: {
          succeeded: {
            type: "array",
            items: {
              type: "string",
              format: "did"
            },
            description: "DIDs for which all pending scheduled actions were successfully cancelled"
          },
          failed: {
            type: "array",
            items: {
              type: "ref",
              ref: "lex:tools.ozone.moderation.cancelScheduledActions#failedCancellation"
            },
            description: "DIDs for which cancellation failed with error details"
          }
        }
      },
      failedCancellation: {
        type: "object",
        required: ["did", "error"],
        properties: {
          did: {
            type: "string",
            format: "did"
          },
          error: {
            type: "string"
          },
          errorCode: {
            type: "string"
          }
        }
      }
    }
  },
